from __future__ import annotations

import ipaddress
from collections.abc import Iterable, Mapping as MappingABC

from app.models.mapping import Mapping
from app.schemas.mapping import normalize_domain, validate_upstream_host

_HEADER = """# ===================================================
# AUTO-GENERATED BY DNS MANAGER
# DO NOT EDIT MANUALLY
# ===================================================
"""


def _validated_port(value: object) -> int:
    if isinstance(value, bool):
        raise ValueError("invalid upstream port")
    try:
        port = int(value)
    except (TypeError, ValueError) as exc:
        raise ValueError("invalid upstream port") from exc
    if port < 1 or port > 65535:
        raise ValueError("invalid upstream port")
    return port


def _validated_scheme(value: object) -> str:
    if value not in {"http", "https"}:
        raise ValueError("invalid upstream scheme")
    return str(value)


def _url_host(value: str) -> str:
    try:
        address = ipaddress.ip_address(value)
    except ValueError:
        return value
    if address.version == 6:
        return f"[{address.compressed}]"
    return address.compressed


def render_nginx_config(
    mappings: Iterable[Mapping],
    defaults: MappingABC[str, object] | None = None,
    *,
    skip_http_domains: Iterable[str] | None = None,
) -> str:
    defaults = defaults or {}
    skipped = {normalize_domain(domain) for domain in (skip_http_domains or ())}
    connect_timeout = int(defaults.get("proxy_connect_timeout", 15))
    send_timeout = int(defaults.get("proxy_send_timeout", 60))
    read_timeout = int(defaults.get("proxy_read_timeout", 60))

    enabled = sorted(
        (mapping for mapping in mappings if mapping.enabled),
        key=lambda mapping: normalize_domain(mapping.domain),
    )

    blocks: list[str] = [_HEADER.rstrip()]

    for mapping in enabled:
        domain = normalize_domain(mapping.domain)
        if domain in skipped:
            continue
        host = validate_upstream_host(mapping.upstream_host)
        scheme = _validated_scheme(mapping.upstream_scheme)
        port = _validated_port(mapping.upstream_port)
        timeout = mapping.custom_timeout or read_timeout

        lines = [
            "server {",
            "    listen 80;",
            f"    server_name {domain};",
            "",
            "    location / {",
            f"        proxy_pass {scheme}://{_url_host(host)}:{port};",
            "        proxy_http_version 1.1;",
            "",
        ]

        if mapping.preserve_host:
            lines.append("        proxy_set_header Host $host;")
        lines.extend(
            [
                "        proxy_set_header X-Real-IP $remote_addr;",
                "        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;",
                "        proxy_set_header X-Forwarded-Proto $scheme;",
            ]
        )

        if mapping.websocket_enabled:
            lines.extend(
                [
                    "        proxy_set_header Upgrade $http_upgrade;",
                    '        proxy_set_header Connection "upgrade";',
                ]
            )

        lines.extend(
            [
                "",
                f"        proxy_connect_timeout {connect_timeout}s;",
                f"        proxy_send_timeout {send_timeout}s;",
                f"        proxy_read_timeout {int(timeout)}s;",
                "    }",
                "}",
            ]
        )
        blocks.append("\n".join(lines))

    return "\n\n".join(blocks).rstrip() + "\n"


def render_https_vhost(
    domain: str,
    mapping: Mapping,
    *,
    redirect_http: bool = True,
    letsencrypt_root: str = "/etc/letsencrypt",
) -> str:
    """Render the HTTPS vhost that the helper writes for one mapping.

    Mirrors ``privileged.ssl_helper.SslHelperOps._nginx_text`` so the console can
    show the exact file without asking the privileged helper to write it.
    """
    site = normalize_domain(domain)
    scheme = _validated_scheme(mapping.upstream_scheme)
    host = validate_upstream_host(mapping.upstream_host)
    port = _validated_port(mapping.upstream_port)
    timeout = int(mapping.custom_timeout or 60)

    blocks: list[str] = []
    if redirect_http:
        blocks.append(
            f"server {{ listen 80; server_name {site}; return 301 https://$host$request_uri; }}"
        )

    lines = [
        "server {",
        "    listen 443 ssl;",
        f"    server_name {site};",
        f"    ssl_certificate {letsencrypt_root}/live/{site}/fullchain.pem;",
        f"    ssl_certificate_key {letsencrypt_root}/live/{site}/privkey.pem;",
        "    ssl_protocols TLSv1.2 TLSv1.3;",
        "    location / {",
        f"        proxy_pass {scheme}://{_url_host(host)}:{port};",
        "        proxy_http_version 1.1;",
    ]
    if mapping.preserve_host:
        lines.append("        proxy_set_header Host $host;")
    lines.extend(
        [
            "        proxy_set_header X-Real-IP $remote_addr;",
            "        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;",
            "        proxy_set_header X-Forwarded-Proto https;",
        ]
    )
    if mapping.websocket_enabled:
        lines.extend(
            [
                "        proxy_set_header Upgrade $http_upgrade;",
                '        proxy_set_header Connection "upgrade";',
            ]
        )
    lines.extend(
        [
            "        proxy_connect_timeout 15s;",
            "        proxy_send_timeout 60s;",
            f"        proxy_read_timeout {timeout}s;",
            "    }",
            "}",
        ]
    )
    blocks.append("\n".join(lines))
    return "\n".join(blocks) + "\n"
